/**
 * High-Precision Vector PDF Report Generator Engine
 * Fetches native backend vector PDF generated by ReportLab or falls back to client print engine.
 */

async function exportFullCosmicPDFReport(astrologyData, numerologyData, careerData) {
    const downloadBtn = document.getElementById("btn-download-pdf");
    if (downloadBtn) {
        downloadBtn.innerHTML = "<span>⏳ Generating PDF Report...</span>";
        downloadBtn.disabled = true;
    }

    try {
        const fullName = document.getElementById("full_name").value || "Cosmic Client";
        const birthDate = document.getElementById("birth_date").value || "1996-07-24";
        const birthTime = document.getElementById("birth_time").value || "14:30";
        const gender = document.getElementById("gender") ? document.getElementById("gender").value : "female";
        const latitude = parseFloat(document.getElementById("latitude_val").value) || 40.7128;
        const longitude = parseFloat(document.getElementById("longitude_val").value) || -74.0060;

        const m1 = document.getElementById("mobile_1") ? document.getElementById("mobile_1").value : "";
        const m2 = document.getElementById("mobile_2") ? document.getElementById("mobile_2").value : "";
        const m3 = document.getElementById("mobile_3") ? document.getElementById("mobile_3").value : "";
        const m4 = document.getElementById("mobile_4") ? document.getElementById("mobile_4").value : "";
        const mobile_numbers = [m1, m2, m3, m4].filter(m => m && m.trim() !== "");

        const [year, month, day] = birthDate.split("-").map(Number);
        const [hour, minute] = birthTime.split(":").map(Number);

        const payload = {
            full_name: fullName,
            year, month, day,
            gender,
            hour, minute,
            latitude, longitude,
            mobile_numbers: mobile_numbers.length ? mobile_numbers : ["9876543210", "9123456789"],
            synastry: window.currentSynastryData || null
        };

        // Call Backend PDF API endpoint
        const response = await fetch(`${API_BASE}/report/pdf`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            throw new Error(`PDF API returned status ${response.status}`);
        }

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `Cosmic_Blueprint_${fullName.replace(/\s+/g, "_")}.pdf`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        window.URL.revokeObjectURL(url);

        if (downloadBtn) {
            downloadBtn.innerHTML = "<span>✅ PDF Downloaded!</span>";
            setTimeout(() => {
                downloadBtn.innerHTML = "<span>📄 Download Full PDF Report</span>";
                downloadBtn.disabled = false;
            }, 3000);
        }

    } catch (err) {
        console.error("Backend PDF Generation error, falling back to window print:", err);
        window.print();
        if (downloadBtn) {
            downloadBtn.innerHTML = "<span>📄 Download Full PDF Report</span>";
            downloadBtn.disabled = false;
        }
    }
}

window.exportFullCosmicPDFReport = exportFullCosmicPDFReport;
